INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('uar-1-enforcer', 1, 'C-50R Enforcer Rail Gun (1)', '1D6x10 M.D. per 80 round burst; one round does 1D6 M.D.', 1, '4000 feet (1219 m)', 'Each burst counts as one of the gunner''s attacks per melee.', '20,000 round drum (250 bursts). Reloading needs special equipment or another giant robot: about 15 minutes untrained, five minutes with Robot Mechanics or for an Operator.', NULL, 'Assault and defense. Fixed forward on the right shoulder with a 30 degree up-and-down arc, so the whole robot turns to aim sideways. Runs off the main nuclear supply. The gun weighs 700 lbs (315 kg).'),
  ('uar-1-enforcer', 2, 'CR-6 Medium-Range Missile Launcher', 'Varies with missile; standard issue high explosive (heavy, 2D6x10 M.D.), plasma (2D6x10) or multi-warhead smart bomb (2D4x10 and +5 to strike)', 1, 'About 40 to 80 miles (64 to 128 km)', 'One at a time or in volleys of two, three or four; a volley is one melee attack.', 'Six', NULL, 'Anti-aircraft and anti-armor (and dragons). The larger launcher over the left shoulder; takes any medium-range missile.'),
  ('uar-1-enforcer', 3, 'CR-10 Short-Range Missile Launchers (2)', 'Any short-range missile; standard issue armor piercing (2D6x10 M.D.), high explosive medium (2D6x10 M.D.) and/or plasma (1D6x10), as printed', 1, 'About five miles (8 km)', 'One at a time or in volleys of two, three or four; a volley is one melee attack.', 'Ten, five in each shoulder', NULL, 'Anti-aircraft and anti-armor (and dragons). One launcher in each shoulder.'),
  ('uar-1-enforcer', 4, 'CR-20 Mini-Missile Turret', 'Varies with missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10)', 1, 'About one mile (1.6 km)', 'One at a time or in volleys of two, three or four; a volley is one melee attack.', 'Twenty', NULL, 'Anti-personnel and defense. A rapid-fire turret in the mid-section; takes any mini-missile.'),
  ('uar-1-enforcer', 5, 'CR-2T Laser Turrets (2)', '2D6 M.D. per single blast, or 4D6 when both lasers fire on one target together', 1, '4000 feet (1219 m)', 'Each single or simultaneous double blast is one of the gunner''s or pilot''s attacks per melee round.', 'Effectively unlimited', NULL, 'Anti-personnel and defense. One on each shoulder, sitting on top of the rail gun and the medium missile launcher; 360 degree rotation, 90 degree arc.'),
  ('uar-1-enforcer', 6, 'Smoke Dispenser', 'Dense smoke cloud covering an 80 foot (24 m) area in front of the unit; can release tear gas instead', 0, NULL, NULL, 'Five total, usually three smoke and two tear gas', NULL, 'On the right leg.'),
  ('uar-1-enforcer', 7, 'Hand to Hand Combat', NULL, 1, NULL, NULL, NULL, NULL, 'The pilot may fight in Mega-Damage close combat instead of firing a weapon. No figures are printed here.'),
  ('uar-1-enforcer', 8, 'Sensor System Note', NULL, 0, NULL, NULL, NULL, '+1 to strike with long-range weapons only, not hand to hand.', 'Special optics on top of the standard robot systems: a thermal-imager, range 2000 feet (610 m), that sees in darkness, shadow and through smoke; infrared and ultraviolet optics (the infrared beam is visible to other infrared optics, can be traced to its source, and is blocked by smoke); and infrared searchlights in the red eyes of the head, range 500 feet (152 m).'),
  ('cr-003-spider-skull-walker', 1, 'C-100R Spider Rail Guns (2)', '2D4x10 M.D. per 80 round burst; one round does 2D4 M.D.', 1, '6000 feet (1828 m)', 'Each burst is one melee attack of the pilot or co-pilot/gunner.', '20,000 rounds per gun (250 bursts each). Reloading needs special equipment and takes about an hour.', NULL, 'Assault and anti-armor. Two cannon-sized guns on the sides of the skull, fixed forward; they are aimed by moving the skull body, which turns 360 degrees and tilts through 90 degrees. Each gun weighs 1.2 tons.'),
  ('cr-003-spider-skull-walker', 2, 'CR-4T Laser Turrets (2)', '6D6 M.D. per dual blast (3D6 M.D. from a single gun)', 1, '4000 feet (1219 m)', 'Each simultaneous double blast is one of the pilot''s melee attacks.', 'Effectively unlimited', NULL, 'Anti-personnel and defense. Double-barreled heavy turrets, one under the chin (front) and one on top of the skull (rear); 360 degree rotation, 90 degree arc.'),
  ('cr-003-spider-skull-walker', 3, 'Smoke Dispenser', 'Dense smoke cloud covering an 80 foot (24 m) area "in front of it" as printed; can release tear gas instead', 0, NULL, NULL, 'Eight total, usually four smoke and four tear gas', NULL, 'In the rear undercarriage. No M.D.C. location is printed for it.'),
  ('cr-003-spider-skull-walker', 4, 'Hand to Hand Combat', 'Body Block/Ram: 1D8 M.D. for every 20 mph (32 km) of speed. Stomp: 3D6 M.D., effective against objects 12 feet (3.6 m) or smaller.', 1, NULL, NULL, NULL, NULL, 'As per Robotic P.S., but the walker is not built for hand to hand; these two attacks are all it has.'),
  ('cr-003-spider-skull-walker', 5, 'Sensor System Note', NULL, 0, NULL, NULL, NULL, '+1 to strike with long-range guns.', 'Standard robot systems plus the same special optics as the UAR-1 Enforcer.'),
  ('cs-mark-v-apc', 1, 'C-40R Rail Gun (1)', '1D6x10 M.D. per 80 round dual burst; one round does 1D6 M.D.', 1, '4000 feet (1219 m)', 'Each dual burst is one of the gunner''s attacks per melee round.', '20,000 round drum (250 bursts). Reloading needs special equipment or a giant-size robot: about 15 minutes untrained, five minutes with robot mechanics or for an Operator.', NULL, 'Assault and defense. Top rear turret; rotates a full 360 degrees with a 70 degree arc. All weapons run off the vehicle''s nuclear supply. The gun weighs 700 lbs (315 kg).'),
  ('cs-mark-v-apc', 2, 'CR-4T Laser Turrets (2)', '6D6 M.D. per dual blast (3D6 from a single blast)', 1, '4000 feet (1219 m)', 'Each simultaneous dual blast is one of the gunner''s attacks per melee round.', 'Effectively unlimited', NULL, 'Anti-personnel and defense. The heading prints "(2)", but the text describes one double-barreled heavy turret in the center of the APC and the M.D.C. list has a single Center Laser Turret. 360 degree rotation, 70 degree arc.'),
  ('cs-mark-v-apc', 3, 'C-2T Dual Laser Turrets (4)', '4D6 M.D. per dual blast (2D6 per single blast)', 1, '4000 feet (1219 m)', 'Each dual (or single) blast is one of the gunner''s attacks per melee round.', 'Effectively unlimited', NULL, 'Anti-personnel and defense. Two light turrets on each side, normally worked by the second gunner; 360 degree rotation, 90 degree arc.'),
  ('cs-mark-v-apc', 4, 'CR-10 Forward Mini-Missile Launchers (2)', 'Any mini-missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10)', 1, 'One mile (1.6 km)', 'One at a time or in volleys of two, three, five, ten or twenty; a volley of any size is one melee attack.', '40 total, twenty per launcher', NULL, 'Anti-personnel and defense. Rapid-fire launchers at the very front, usually fired by the pilot.'),
  ('cs-mark-v-apc', 5, 'Forward Auto-Cannons (2)', '1D6x10 M.D. per fragmentation round, to a 20 foot (6.1 m) radius', 1, '2000 feet (610 m)', 'Each blast is one of the gunner''s melee attacks.', '60 total, thirty per cannon', NULL, 'Anti-personnel and defense. One on each side of the mini-missile launchers, worked by the pilot or copilot; each rotates 180 degrees.'),
  ('cs-mark-v-apc', 6, 'Hatch Laser Guns (3)', '2D6 M.D. per single blast', 1, '4000 feet (1219 m)', 'Each blast is one of the gunner''s melee attacks.', 'Effectively unlimited', NULL, 'Anti-personnel and defense. Rifle-type lasers at the two forward hatches and the rail gun hatch, manned by crew or by carried troops; 360 degree rotation, 90 degree arc. Built for range over damage.'),
  ('cs-mark-v-apc', 7, 'Smoke Dispensers (2)', 'Dense smoke cloud covering a 40 foot (12 m) area in front of the unit; can release tear gas instead', 0, NULL, NULL, 'Twenty total, ten each; usually half smoke and half tear gas', NULL, 'One on each side of the APC.'),
  ('cs-mark-v-apc', 8, 'Hand to Hand Combat', NULL, 0, NULL, NULL, NULL, NULL, 'None of its own; see the combat troops being transported.'),
  ('cs-mark-v-apc', 9, 'Sensor System Note', NULL, 0, NULL, NULL, NULL, NULL, 'Has all the basic features of the robot vehicles.'),
  ('afc-050-deaths-head-transport', 1, 'C-200DH Rail Gun (1)', '2D4x10 M.D. per 100 round burst; one round does 1D4 M.D.', 1, '10,000 feet (3048 m)', 'Each burst is one of the pilot''s melee attacks.', '40,000 rounds per gun (400 bursts each). Reloading needs special equipment and takes about an hour.', NULL, 'Assault and anti-armor. One twin-cannon turret on top of the forward skull section; 360 degree rotation, 90 degree tilt. Powered by the main nuclear supply. Each gun weighs 1.2 tons.'),
  ('afc-050-deaths-head-transport', 2, 'CR-51 Medium-Range Missile Launchers (2)', 'Any medium-range missile; standard issue high explosive heavy (3D6x10 M.D.) and plasma (4D6x10 M.D.) and/or multi-warhead smart bomb (5D6x10 and +5 to strike)', 1, 'About 40 to 80 miles (64 to 128 km)', 'One at a time or in volleys of two or four; a volley is one melee attack.', '10 missiles, five in each launcher', NULL, 'Anti-aircraft and anti-armor. Hidden in the forehead of the skull behind a sliding panel. No M.D.C. location is printed for them.'),
  ('afc-050-deaths-head-transport', 3, 'CR-6T Laser Turrets (6)', '1D4x10 M.D. per dual blast from one turret; 3D4x10 M.D. if all three on a side lock onto one target', 1, '6000 feet (1829 m)', 'Each dual blast is one melee attack of the pilot or gunner; training all three on one target uses two melee attacks.', 'Effectively unlimited', NULL, 'Anti-personnel and defense. Three heavy turrets on each side; 180 degree rotation, 90 degree arc. Normally each turret engages its own target.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('afc-050-deaths-head-transport', 4, 'Smoke Dispenser', 'Dense smoke cloud covering an 80 foot (24.4 m) area behind the unit; tear gas may be substituted for riot control', 0, NULL, NULL, 'Twelve total, usually eight smoke and four tear gas', NULL, 'In the rear undercarriage. No M.D.C. location is printed for it.'),
  ('afc-050-deaths-head-transport', 5, 'Hand to Hand Combat', NULL, 0, NULL, NULL, NULL, NULL, 'None of its own; only through the combat troops it carries.'),
  ('afc-050-deaths-head-transport', 6, 'Sensor System Note', NULL, 0, NULL, NULL, NULL, '+1 to dodge at cruising speeds and +2 to dodge when flying over 300 mph (480 km). Trained CS pilots get an additional +10% to pilot it.', 'Standard systems plus a thermal-imager, range 2000 feet (610 m); infrared and ultraviolet optics (the infrared beam can be seen and traced by other infrared optics and is blocked by smoke); headlights in the face that double as infrared searchlights, range 500 feet (152 m); and enhanced radar that tracks up to 192 targets at 200 miles (320 km). City maneuvering and combat usually call for piloting rolls.'),
  ('afc-023-sky-cycle', 1, 'CR-21 Mini-Missile Launchers (2)', 'Any mini-missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10)', 1, 'One mile (1.6 km)', 'One at a time or in volleys of two, three, four or five; a volley is one melee attack.', '20, ten missiles in each launcher', NULL, 'Anti-personnel and anti-armor. One on each side of the cycle, near the landing gear.'),
  ('afc-023-sky-cycle', 2, 'CR-4T Laser Turret (1)', '6D6 M.D. per dual blast (3D6 per single blast)', 1, '4000 feet (1219 m)', 'Each dual (or single) blast is one of the pilot''s attacks per melee round.', 'Effectively unlimited', NULL, 'Anti-personnel and defense. A heavy turret in the nose that swings 180 degrees side to side and cannot elevate.'),
  ('afc-023-sky-cycle', 3, 'Smoke Dispenser', 'Dense smoke cloud covering an 80 foot (24 m) area behind the unit; can release tear gas instead to quell riots', 0, NULL, NULL, 'Six loads total, usually three smoke and three tear gas', NULL, 'In the rear undercarriage. No M.D.C. location is printed for it.'),
  ('afc-023-sky-cycle', 4, 'Hand to Hand Combat', NULL, 0, NULL, NULL, NULL, NULL, 'None.'),
  ('afc-023-sky-cycle', 5, 'Sensor System Note', NULL, 0, NULL, NULL, NULL, '+3 to dodge at cruising speeds and +5 to dodge when flying over 250 mph (400 km). Trained CS pilots get an additional +10% to pilot it.', 'All the standard robot sensors and communications, radar included. City combat, dogfights and high-speed maneuvers usually call for a piloting skill check.'),
  ('ng-x9-samson-power-armor', 1, 'NG-202 Super Rail Gun (1)', '1D6x10 M.D. per 60 round burst; one round does 1D6 M.D.', 1, '4000 feet (1219 m)', 'Each burst counts as one melee attack.', '6000 round drum (100 bursts). A second drum can hang under the rocket jets; swapping it in takes another Samson or a character with a strength of 26 or higher. Reloading a drum takes about 5 minutes untrained, one minute for someone trained in Samson power armor.', NULL, 'Assault and defense. Standard equipment, wired straight into the suit''s nuclear supply. Gun 210 lbs (94.5 kg); one Super Ammo-Drum 300 lbs (135 kg).'),
  ('ng-x9-samson-power-armor', 2, 'Forearm Rocket Launcher', 'Varies with missile; standard issue armor piercing (1D4x10 M.D.) or plasma (1D6x10); fragmentation (5D6 M.D.) for anti-personnel work', 1, 'Usually about one mile', 'One or two at a time; both count as one melee attack.', 'Four total, two per arm', NULL, 'Anti-aircraft and defense. A mini-missile launcher in each forearm; takes any mini-missile.'),
  ('ng-x9-samson-power-armor', 3, 'Knuckle Blades', 'Adds 1D6 M.D. to punch attacks', 1, 'Hand to hand', NULL, NULL, NULL, 'Three blades that slide out from the hand.'),
  ('ng-x9-samson-power-armor', 4, 'Energy Rifles and other normal weapons', 'By weapon.', 1, NULL, NULL, NULL, NULL, 'Not a built-in system: hand weapons ride in a compartment about the size of a footlocker.'),
  ('ng-x9-samson-power-armor', 5, 'Hand to Hand Combat', 'Double damage from Leap Kick attacks', 1, NULL, NULL, NULL, NULL, 'Mega-Damage combat in place of a weapon; skills and bonuses depend on whether the pilot has Robot Combat Basic or Elite.'),
  ('ft-005-flying-titan-power-armor', 1, 'Wing Lasers (2)', '2D6 M.D. per blast', 1, '4000 feet (1219 m)', 'Each shot counts as one melee attack.', 'Effectively unlimited', NULL, 'Assault and defense. A small turret under each wing; 360 degree rotation, 90 degree arc, fed from the suit''s nuclear supply. Fired by voice command or a concealed stud on the forearm.'),
  ('ft-005-flying-titan-power-armor', 2, 'Wing Rockets', 'Varies with missile type; the short-range missiles are generally more powerful', 1, 'Varies with missile type; 1-5 miles (1.6 to 8 km)', 'One at a time or in volleys of two, three or four; a volley of any size is one melee attack.', 'Total of 12 mini-missiles or 6 short-range missiles (six mini or three short-range per wing)', NULL, 'Anti-aircraft and anti-armored vehicle. Launched by voice command or hidden forearm studs, like the lasers.'),
  ('ft-005-flying-titan-power-armor', 3, 'Energy Rifles and other normal weapons', 'By weapon.', 1, NULL, NULL, NULL, NULL, 'Not a built-in system. The slim armor leaves room for a sidearm, a rifle and the usual belts, harness and pouches, though belts and containers tend to tear loose above 100 mph (160 km).'),
  ('ft-005-flying-titan-power-armor', 4, 'Hand to Hand Combat', NULL, 1, NULL, NULL, NULL, NULL, 'The pilot may fight in Mega-Damage hand to hand combat instead of using a weapon. No figures are printed here.'),
  ('tr-001-titan-combat-robot', 1, 'T-001 Rapid-Fire Rail Gun (1)', '1D4x10 M.D. per 80 round burst; one round does 1D4 M.D.', 1, '4000 feet (1219 m)', 'Each burst counts as one melee attack.', '20,000 round drum (250 bursts). Reloading needs special equipment or another giant robot: about 15 minutes untrained, five minutes with Robot Mechanics or for an Operator.', NULL, 'Assault and defense. Fixed forward on the right forearm, so the whole arm is raised to aim it, as with a pistol. The gun weighs 900 lbs (405 kg).'),
  ('tr-001-titan-combat-robot', 2, 'T-001 Shoulder Missile Launchers (2)', 'Varies with missile type; any medium-range missile', 1, '40-80 miles (64 to 128 km)', 'One at a time or in volleys of two, three or four.', 'Ten total, five each shoulder', NULL, 'Anti-aircraft and anti-armor. Medium-range launchers set in the shoulders.'),
  ('tr-001-titan-combat-robot', 3, 'T-001 Mini-Missile Leg Launchers (2)', 'Varies with missile; standard issue fragmentation (5D6 M.D.) and plasma (1D6x10)', 1, 'One mile (1.6 km)', 'One at a time or in volleys of two, three or four.', 'Twelve, six on each leg', NULL, 'Anti-personnel and defense. A small launcher on the side of each leg; takes any mini-missile.'),
  ('tr-001-titan-combat-robot', 4, 'T-001 Laser Turrets (1)', '4D6 per twin blast (2D6 M.D. per single blast)', 1, '2000 feet (610 m)', 'Each (single or) dual blast counts as one melee attack.', 'Effectively unlimited', NULL, 'Anti-personnel and defense. One turret in the chest with a 90 degree up-and-down arc.'),
  ('tr-001-titan-combat-robot', 5, 'Hand to Hand Combat', 'Retractable Vibro-Claws add 2D6 M.D. to open hand slap/clawing and tearing damage', 1, 'Hand to hand', NULL, NULL, NULL, 'The pilot may fight in Mega-Damage hand to hand combat instead of using a weapon.'),
  ('atlas-mark-i-assault-robot', 1, 'Giant Rune Sword (1)', '2D6x10 M.D. in physical attacks, or a 1D6x10 M.D. force blast', 1, 'Hand to hand; force blast 1,000 feet (305 m)', 'Force blast: equal to the hand to hand attacks of the pilot (usually six).', NULL, NULL, 'Hand to hand combat and anti-robot, secondary defense. A two-handed rune blade made for giants at least 30 feet (9 m) tall, taken from an old temple in an empty dimension; 600 lbs (270 kg). Through a techno-wizard link the pilot can use its powers only while inside the robot. Three times per 24 hours each it casts Blinding Flash, Globe of Daylight, Cloud of Smoke, Wall of Flame, Circle of Flame, Fuel Flame and Impervious to Fire.'),
  ('atlas-mark-i-assault-robot', 2, 'Particle Beam Cannon (1)', '2D6x10 M.D. per blast', 1, '3000 feet (914 m)', 'Equal to the hand to hand attacks of the pilot or gunner.', 'Effectively unlimited', NULL, 'Anti-robot or anti-vehicle, secondary defense. Bought from an advanced alien race, tied into the robot''s power system and hidden in the left arm. Weighs 3 tons.'),
  ('atlas-mark-i-assault-robot', 3, 'Eye Beams (2)', '4D6 M.D. per blast', 1, '2000 feet (610 m)', 'Equal to the hand to hand attacks of the pilot or gunner.', 'Effectively unlimited', NULL, 'Defense, secondary anti-personnel. Lasers in the eyes, for close work against infantry and power armor.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('atlas-mark-i-assault-robot', 4, 'Techno-Wizard Modifications', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon and not numbered in the book; printed as its own block before the weapon systems. Impervious to Energy: thought-activated for 20 P.P.E. or 40 I.S.P., lasting 20 minutes. Link to Rune Weapon: lets the robot wield the giant rune sword as a living being would and cast its spells. Damage Restoration: restores depleted M.D.C. at about 10% per day. Swim as a Fish: 20 P.P.E. for 20 minutes.'),
  ('ahriman-mark-i-rune-assault-suit', 1, 'Techno-Wizard Cannons (2)', '2D4x10 M.D., the equivalent of a 20th level fire ball', 1, '2,000 feet (610 m)', 'Equal to combined hand to hand attacks.', 'Draws P.P.E. from the demon inside; effectively unlimited', NULL, 'One in each arm.'),
  ('ahriman-mark-i-rune-assault-suit', 2, 'Spikes', '4D6 M.D. each', 1, NULL, 'One at a time or in volleys of 2 or 4.', '40 total: 10 in each knee, 7 per arm and 3 per shoulder. They magically regenerate after 24 hours.', NULL, 'The large spikes on the armor launch like rockets at an attacker. No range is printed.'),
  ('ahriman-mark-i-rune-assault-suit', 3, 'The Separation', 'Each demon: 1D4 M.D. restrained claw strike, 1D4x10 restrained strike, 3D4x10 power strike (as printed)', 1, NULL, NULL, NULL, 'Each demon: P.S. 40, +4 to strike, parry and dodge.', 'On a mental command the suit comes apart and each piece, or whichever pieces Ahriman releases, turns back into a demon; a second command reassembles it. A demon has the M.D.C. of the piece it formed (a forearm becomes a 200 M.D.C. demon). A slain demon''s M.D.C. is deducted from the main body, and depleting the main body shuts the demons down.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 10 machines are in' AS assertion, count(*) AS got, 10 AS want
  FROM vehicles WHERE slug IN ('uar-1-enforcer', 'cr-003-spider-skull-walker', 'cs-mark-v-apc', 'afc-050-deaths-head-transport', 'afc-023-sky-cycle', 'ng-x9-samson-power-armor', 'ft-005-flying-titan-power-armor', 'tr-001-titan-combat-robot', 'atlas-mark-i-assault-robot', 'ahriman-mark-i-rune-assault-suit');
SELECT 'their 85 locations are in' AS assertion, count(*) AS got, 85 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('uar-1-enforcer', 'cr-003-spider-skull-walker', 'cs-mark-v-apc', 'afc-050-deaths-head-transport', 'afc-023-sky-cycle', 'ng-x9-samson-power-armor', 'ft-005-flying-titan-power-armor', 'tr-001-titan-combat-robot', 'atlas-mark-i-assault-robot', 'ahriman-mark-i-rune-assault-suit');
SELECT 'their 54 weapon entries are in' AS assertion, count(*) AS got, 54 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('uar-1-enforcer', 'cr-003-spider-skull-walker', 'cs-mark-v-apc', 'afc-050-deaths-head-transport', 'afc-023-sky-cycle', 'ng-x9-samson-power-armor', 'ft-005-flying-titan-power-armor', 'tr-001-titan-combat-robot', 'atlas-mark-i-assault-robot', 'ahriman-mark-i-rune-assault-suit');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('uar-1-enforcer', 'cr-003-spider-skull-walker', 'cs-mark-v-apc', 'afc-050-deaths-head-transport', 'afc-023-sky-cycle', 'ng-x9-samson-power-armor', 'ft-005-flying-titan-power-armor', 'tr-001-titan-combat-robot', 'atlas-mark-i-assault-robot', 'ahriman-mark-i-rune-assault-suit') AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~084-rue-and-pantheons-machines.sql');
